#include <stdio.h>
#include <ctype.h>

int main() {
    const char *word = "Education";
    int vowels = 0, consonants = 0;
    for (int i = 0; word[i] != '\0'; i++) {
        char c = tolower(word[i]);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            vowels++;
        } else if (isalpha(c)) {
            consonants++;
        }
    }
    printf("vowels=%d consonants=%d\n", vowels, consonants);
    return 0;
}
